quests[91000] = { id = 91000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Humble Servant", progress = "There is much to do, {name}.", completion = "Good work, {name}. Things are starting to look better.", objectives = "Aid the people of Hammerfall in their recovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91001] = { id = 91001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear de Way", description = "With dey magic and dey line broken, de Twilight's Blade is losin' ground.\n\nWe must take advantage of dey turned backs.\n\nI will lead de charge through de ravine to de Conquerer's Sanctum beyond. Mor'duun is there, keepin' his coward-body safe from our spears and axes.\n\nHe won't be safe much longer.", progress = "We must act--now!", completion = "Mor'duun may laugh now, holed up in de Sanctum.\n\nBut we will get de last laugh.", objectives = "Regroup with Zul'jarra, Zul'jan, and Lady Liadrin at the foot of Conquerer's Sanctum in Broken Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91009] = { id = 91009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durable Information Storage Container", description = "Adventurer, can you hear me? I've discovered a smaller titan device, the Durable Information Storage Container, which can fit on yer belt. I've deduced they'll be able tae play smaller titan discs, granting ye boons ye can use anywhere. \n\nEach of these devices need a jump start. If ye kick up enough dust in these delves it should generate a spark that the device will detect and collect. It should be enough tae power it for yer lifetime.", progress = "The overcharging is key.", completion = "Attach the device. Yes! The device is powered on. \n\nOkay... If I just start the initialization sequence... and it's up. There are already two discs inside. And the menu will list areas where other miniature titan discs can be found. I'm thinkin' I can improve the device, but I need time. Find me later and see.", objectives = "Complete a Delve to charge the device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91022] = { id = 91022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endeavor Reward" }
quests[91023] = { id = 91023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endeavor Reward" }
quests[91024] = { id = 91024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endeavor Reward" }
quests[91026] = { id = 91026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering an Upgrade", description = "Hello? Hello? You're back! Perfect!\n\nI was studying the titan console and gathering a bunch of new information from the overcharged areas including the faulty directives that were found. This might be the key to this unexpected behavior, but I'll need more time tae know for sure.\n\nReturn to the delves and we can check the results of the faulty directives, I can use the information to create an upgrade for yer belt!", progress = "Were ye successful?", completion = "Here, yes... With that information I can make some final tweaks. And adding this directive...\n\nAh! That should do it. If you insert this into yer durable information storage container, it should update the effectiveness of the device's, um... effects.", objectives = "Complete any Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91030] = { id = 91030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Titan Directives", description = "My calculations need a lot more data. I've got another upgrade card nearly finished, but I'm not sure if it will integrate properly.\n\nBut if ye go back into the delve spaces and defeat more of the enemies, I can see how they react. Based on their reactions, I can put the final touches on this upgrade for yer belt.", progress = "I can't wait to see the data!", completion = "Hmm, as I suspected. Yes... I need to adjust this here... done.\n\nThe good news is that this upgrade will nae make yer belt explode! I thought there was a small chance, but no longer. Yer data proved that I set the power too high. So... good thing I had ye do tha' extra check, right?", objectives = "Complete any Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91031] = { id = 91031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing it to the Limit", description = "I realized after ye left last time that I might have worried ye a wee bit with the whole exploding belt upgrade possibility. I'm sorry. I get a bit excited sometimes.\n\nI do think I can get even more power out o' the belt. At least a bit more. Safely of course! In yer data, I've seen that you've encountered many enemies as ye entered many delves. That's the key, return one more time for this last upgrade for yer belt.", progress = "I cannae wait to see if I was correct!", completion = "The data from that last excursion provided what I needed for another upgrade. But this is the last upgrade we can do for the belt, unless we want a major meltdown. Of course a meltdown would tell us a lot about the design...\n\nMa always said, \"Dagran! If yer gonna destroy ancient, irreplaceable artifacts, destroy yer own.\" So this is the last upgrade.\n\nHere is the last upgrade card. Thank ye for yer help. I hope we get a chance to experiment more in the future!", objectives = "Complete any Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91033] = { id = 91033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring 'Construct'ing", description = "Welcome back, adventurer. I have a simple request for ye. I need ye tae continue monitorin' these titan constructs. \n\nWe have seen them moving around Azeroth in different locations, but I've not yet figured out their end goal or what instructions they might have. Perhaps if ye can gather more information, an insight will present itself.", completion = "Their behavior seems mostly unchanged. This is very frustrating. Also if yer data is correct, it looks like they might be calmin' down. \n\nWe will have tae see if this observation is true. And here is some additional gear that we have collected. I hope it has served ye well over the course of our scientific endeavors!", objectives = "Complete an Overcharged Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91035] = { id = 91035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Construct De-Escalation", description = "Yer previous results showed a reduction in the overcharge present in the constructs. We must see if that was a one-off or if the reduction is escalatin'...\n\nHead back into these overcharged areas and test out the charge on the constructs, then report back.", completion = "Wow! Tha' drop off is huge. If this holds steady, these constructs could be gone soon! \n\nWe still don't know what prompted them to come out! What if we never know? I hope that they return.\n\nOh, no! I don't want them tae mess things up. I just hate tae leave this unsolved. \n\nAt least we will be more prepared if we do see them again. Thank ye for yer help, {name}. I've checked the numbers and yer belt should still work, even if the constructs do retreat. \n\nAnd one last box of supplies for yer help.", objectives = "Defeat 5 constructs and complete an Overcharged Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91038] = { id = 91038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellhunters Wanted", description = "<A scorch-marked missive has been nailed to this wall.>\n\nHELL COMES FOR YOU!\n\nNow that we have your attention, please be warned that shards of brimstone have entered this world. They are warm to the touch and should not, under any circumstances, be stabbed into your head, the head of anyone else, or any other vital organ of you or anyone near you.\n\nPlease bring any shards you find IMMEDIATELY to us in Dornogal.\n\nAnd if you see any tiny little minions carrying a bag of treasures, KILL THEM ON SIGHT.", completion = "We appreciate your interest in aiding us.\n\nShards of our timeline have made their way into your world. It is a place more grim and dark than your own, where some villains became heroes and some heroes never had the chance.\n\nHelp us locate these hellish fragments out of time and return them to their rightful place, and we will provide you with armors tempered by the fires of our world.\n\nAnd should you find any Treasure Goblins that lurk in your world, we implore you to slay the abominations.", objectives = "Bring the missive to Baranar in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91039] = { id = 91039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerin's Request", description = "{name},\n\nGeya'rah and Danath have arrived in Dornogal. They both seem upset about rising tensions in the Arathi Highlands. It sounds serious.\n\nCan you come to Dornogal? I believe your presence can help the situation.\n\nFaerin", completion = "{name}! Thank you for coming.", objectives = "Speak to Faerin Lothar in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91040] = { id = 91040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vexatious Vilebranch" }
quests[91041] = { id = 91041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91042] = { id = 91042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91044] = { id = 91044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger of the Void", description = "I did all I could to prevent this outcome. If you hadn't pushed him through the portal the unrestrained void energy would've collapsed the cave around us.\n\nHe was strong. In a way, I think that worked against him.\n\nMeet me back in Shan'dorah. I need to report to Umbric and let him know what happened here.", progress = "I could feel the void energies roiling from here, {class}. What exactly happened?", completion = "I sincerely hope that Adarus is well, and that he doesn't blame us. The ren'dorei have enough enemies as it is.\n\nI am excited that Leona has made a breakthrough. Though she never would have succeeded without your help.", objectives = "Reconvene with Magister Umbric and Leona back in Shan'dorah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91052] = { id = 91052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Overcharged Delves", description = "Something has caused hostile titan constructs to activate and enter various caverns and spaces around Khaz Algar. Venture to these locations and investigate and eliminate the threat they pose.", completion = "It is unnerving to not know what has forced these hostile titan units to surface. But due to your efforts their threat is at an end.", objectives = "Complete an Overcharged War Within Delve at any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91061] = { id = 91061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Chaos", description = "You may think this ironic, but our time is running short, {name}. Great forces threaten more than one world's future.\n\nNozdormu won't like it, but I must hasten our study with experimentation. I have isolated a fractured timeline for you to explore. But be warned--this realm is devoid of all hope. It is the only way I can truly prepare us for what is to come.\n\nI have established a research console by the fel monument behind you. Use it to enter this forbidden future so that we may learn the unknowable.", progress = "Have you seen the dark times that could have been?", completion = "You are braver than I thought, {name}.\n\nPlease continue to experiment. I will not let us enter dangerous futures unprepared.", objectives = "Explore the Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91062] = { id = 91062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Bridges", description = "I make one last request of you before you return with Liadrin to Silvermoon, hash'ura.\n\nFind Zul'jan. None have seen him since returnin' to Amani'Zar.\n\nOn de way back here, I confronted him about takin' our soldiers to Broken Throne against my orders.\n\nPeople died dat shouldn't have. I asked him what he don't understand about dat.\n\nHe didn't argue. He was blank. His body was there, but his mind?\n\nSometimes he seeks peace in de sound of ocean waves.\n\nYou might find him on de Skybridge.", completion = "Glad I found you. Zul'jarra let me know you would be searching this area for Zul'jan, but this land is still so unfamiliar to me.\n\nIf you have found him and are finished enjoying the party, we should return to Silvermoon.", objectives = "Seek out Zul'jan upon the Skybridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91063] = { id = 91063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blooming Lattice", description = "You're that stranger I've been hearing about, aren't you? I'm Su'meera, apprentice painter to Ja'kul. You heard of him? No? Maybe his work hasn't made it to your lands. That makes sense, I guess.\n\nAnyhow, I heard you like helping people out. Well, a few important things went missing when Ja'kul was attacked and killed. I want them back.\n\nWill you meet me near Blooming Lattice?", completion = "Thanks for coming. I wasn't sure you would. Up the hill that way is Blooming Lattice--a settlement of rutaani who are quite vicious.\n\nTheir leaders killed Ja'kul, and took his things. I want them back!", objectives = "Meet Su'meera near Blooming Lattice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91065] = { id = 91065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purloining Petals", description = "A couple of days ago, a group of rutaani attacked and killed my mentor, Ja'kul. When they did, their stupid birds stole a few things from him. Those petals-for-brains will make off with anything shiny that isn't thorned down.\n\nWill you recover Ja'kul's things for me? I'm a painter, not a fighter. I wouldn't last very long in there on my own.", progress = "Those birds would steal your head if it wasn't attached to your shoulders. Especially if you were wearing a shiny hat or helm. Right off your shoulders!\n\n<She pauses for a moment as if picturing this, then turns slightly green and shudders.>", completion = "You did it! I knew they had these, those rotten weed-for-brains scavengers!\n\nI know it's silly to be upset about things like a favorite spoon, but they took Ja'kul's life. I won't let them take anything else from him.\n\nYou're the best, {name}.", objectives = "Recover stolen objects from Blooming Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91066] = { id = 91066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewmaster's Kitchen", description = "Good, you've brought the supplies. Now, we begin the feast. We'll need plenty of food to keep up our strength.\n\nThe menu's simple, but worthy: Barley Stew, Stone-baked Pretzels, and a strong brew to fuel the Horde!\n\nAre you prepared to learn?", progress = "Start the fire and get to work!", completion = "Hah! I can smell those pretzels from here. You've cooked up a feast fit to silence even the grumbling of dwarves!", objectives = "Follow the steps to cook Brewfest food and a delicious Brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91067] = { id = 91067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Grub", description = "Ah, you're here. Brewfest has begun-but we've got a problem. Can't have a proper feast without food, and some thieving hozen thought it'd be clever to snatch our grub.\n\nHere's what you'll do: track down those hozen and take back what's ours. You might find a few bags just lying around too-grab those. Once you've got the goods, toss them in the wagon behind me.", progress = "The feast won't come together without those ingredients!", completion = "You've done it! The cooks will be pleased.", objectives = "Collect Bags of Brewfest Ingredients and deposit them at the wagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91068] = { id = 91068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serving with Style", description = "You've proven your strength at cooking, now it's time to prove it on the floor! Brewfest isn't just about feastin-it's about bringing the revelry to every corner of the camp.\n\nYou'll be taking orders, hauling plates, and pouring ale like a true warrior of celebration.\n\nNow get out there and show them what real service looks like! Brewfest don't run on empty mugs!", progress = "Remember to serve with a smile!", completion = "I'd say you've earned yourself a break and a strong brew after all that work. But don't go getting soft on me! Brewfest isn't over, and there's still plenty of work to be done.", objectives = "Take the customer's order and serve the food to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91069] = { id = 91069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Tolbani", description = "Me and Tolbani had loaded de skiff with medicine, steel, and food to bring upriver to de forward camp.\n\nIt was meant to be a quiet run: no trouble, and no eyes on us.\n\nBut in de shallows, de murlocs came swarmin' out of de reeds all foam and teeth. Dey hit us hard--too fast to fight back proper. We tipped and lost de cargo. I barely made it to shore.\n\nTolbani didn't. I dragged his dart-riddled body here.\n\nDe murlocs must pay for what dey have done.", progress = "Bleed de mindless beasts. Make dem suffer for killin' Tolbani.", completion = "Do you hear dat?\n\nIt's quiet.\n\nDat is de sound of vengeance.", objectives = "Kill 12 murlocs in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91070] = { id = 91070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaim the Goods", description = "While I was limping back from de river, I spotted a few of de murlocs dragging our food bags through de mud. They weren't working together either--kept snapping at each other, trying to snatch de best pieces for themselves.\n\nI saw one of them stash a whole satchel behind a fallen tree. Another buried something under a pile of rocks. Greedy little monsters think they can steal from us and get away with it.", progress = "Yes, {class}?", completion = "Good. That's all of it.", objectives = "Find 6 stolen Food Provisions in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91071] = { id = 91071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menace of Atal'Abasi", description = "Our boat didn't ground on its own.\n\nWe were fightin' de murlocs, and then suddenly we were in de air.\n\nDats when I saw him--one dat wasn't like de rest. Bigger. Stronger. When he attacked, de other murlocs scattered.\n\nHe picked up our boat like it weighed nothin' and hurled it on de rocks. I've never seen a murloc do somethin' like that.\n\nWe're gonna keep losin' people and supplies if dat muscle-bound murloc is watchin' de river.", completion = "I saw de small ones run away in terror. Well done, {class}.", objectives = "Find and slay Mrruk the Musclefin in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91084] = { id = 91084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Shadows", description = "Though we've triumphed over Ruia and the Lightbloom for now, more remains to be done. The elders will want to convene regarding the Hara'ti's new place in the world, now that we have stepped out from the shadows of our past.\n\nOur reticence and fear will not vanish overnight. But this is an important first step.\n\nWe will be fine, {name}. Let Orweyna and I deal with the elders. When the time comes, the Hara'ti shall be at your side. For now, though, I'd imagine you have more pressing matters to attend to.", completion = "When Halduron burst into a war council shouting about hidden worlds and ancient warriors, I thought he had gone mad. But now that I've seen the haranir with my own eyes...\n\nWe are lucky to have them as potential allies. And lucky to have you, I'd say, in brokering that relationship.\n\nThere is more for us to do. But I've no doubt that the Hara'ti will prove vital allies to Silvermoon in the days to come.", objectives = "Return to Regent Lord Lor'themar Theron in the Sanctum of Light in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91085] = { id = 91085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Petal Bristles", description = "Ja'kul was out hunting petalwings when the rutaani came upon him and killed him. We use their feathers for some of our paintbrushes. They are especially useful in helping the young sprouts learn how to be more precise and delicate. \n\nWhile you're up there, will you bring me back some of their plumes?", progress = "Have you gathered the petalwing plumes I asked for? They're essential for the lessons of the younger haranir.", completion = "Thank you for bringing me these feathers! I will use one of them to paint a special memorial for Ja'kul. The rest will go to the children. \n\nI suppose it will fall to me now to teach them.", objectives = "Collect 8 Petalwing Plumes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91086] = { id = 91086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nipping the Buds", description = "The rutaani of Blooming Lattice were behind the attack on Ja'kul. They're led by a Prime Bloomwarden who's even more vicious. I hate them and they're all terrible!\n\nHow about you go prune the overgrowth and make the rest of us safer?", completion = "Is it done? Thanks. It won't bring Ja'kul back, but now they won't be hurting anyone else.", objectives = "Kill rutaani and the Prime Bloomwarden in Blooming Lattice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91087] = { id = 91087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reports Returned", description = "I will go to Silvermoon but... I will return here to advise Zul'jarra.\n\nI feel I let my past and my prejudices get in the way of my judgement regarding the Amani. You could say that being a hash'ura is a befitting atonement but... I feel drawn to stay, perhaps to help Zul'jarra in guiding her people back to the loa.\n\nI will go to Silvermoon with you to bear the report--and Lor'themar's reaction.\n\nIf we go now, we may return to... party.\n\n<A small smile cracks Liadrin's usually stoic face.>", completion = "<Lor'themar raises an eyebrow and frowns slightly. You can tell he is fighting back exasperation and anger.>\n\nThis is a... very unexpected turn of events. Yet still more will unfold in front of us, I'm sure.", objectives = "Report to Lor'themar Theron in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91088] = { id = 91088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind the Falls", description = "The scroll you brought back was left behind for me by my mentor, Ja'kul. I didn't even have a chance to read it before it was stolen away! \n\nJa'kul left directions in the scroll to a cave that's behind a waterfall in Blooming Lattice. I'm not sure what we'll find there, but I would really appreciate if you came along while I check it out. Will you meet me there?", completion = "This is incredible! I can't believe there's a whole cave back here. And Ja'kul left behind a vision stone for me.", objectives = "Meet Su'meera in the cave behind the waterfall in Blooming Lattice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91089] = { id = 91089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeating Ky'veza", description = "So she's here to collect a bounty, eh?\n\nDid nae one tell her it's rude to try and kill a Champion of Azeroth? Or a Bronzebeard, for that matter?", completion = "Whew! Good riddance.\n\nI cannae stand all tha skulking around and teleportin' about tha place.\n\nMight be time for a wee bit of vacation after all this excitement.", objectives = "Increase your item level to challenge Ky'veza in her tier 8 delve on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91090] = { id = 91090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pesky Pests", description = "Nearby creatures are suffering an infection of Light, and are being drawn to the Sunbath. Our guests find it disturbing. That is a problem, when one is trying to enjoy a tranquil escape from the world.\n\nI confess, having one run into your leg while you are swimming can be unnerving.\n\nPlease, dissuade the invading sungrubs from joining us, and take to the sky to chase off those persistent butterflies.", progress = "Are the insects giving you trouble?", completion = "That wasn't so bad, was it? \n\nVal does get a bit dramatic, but you performed wonderfully.", objectives = "Kill 10 Sungrubs and fly to chase away 10 Persistent Butterflies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91093] = { id = 91093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Just a Phase", description = "Untethered Space represents an ongoing danger to our people on K'aresh. It is infested with banished souls, broken technology, and monsters of all kinds.\n\nAid the K'aresh Trust and defeat our foes in Untethered Space. You may use the Phase Conduits to navigate between the remnants of K'aresh while phase diving.", progress = "I dream of a day when we K'areshi can roam these lands freely and without fear.", completion = "Your assistance is most appreciated, {race}. The Trust was wise in appointing you to aid our efforts.", objectives = "Complete activities while phase diving in Untethered Space on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91095] = { id = 91095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magister Sunbreaker (Normal)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "Hunt down Magister Sunbreaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91096] = { id = 91096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magistrix Emberlash (Normal)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "Hunt down Magistrix Emberlash and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91097] = { id = 91097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Senior Tinker Ozwold (Normal)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "Hunt down Senior Tinker Ozwold and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91098] = { id = 91098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: L-N-0R the Recycler (Normal)", objectives = "Hunt down L-N-0R the Recycler and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91099] = { id = 91099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Mordril Shadowfell (Normal)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n\nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "Hunt down Mordril Shadowfell and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91100] = { id = 91100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Deliah Gloomsong (Normal)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "Hunt down Deliah Gloomsong and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91101] = { id = 91101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Phaseblade Talasha (Normal)", description = "Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me.\n\nMy scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.", objectives = "Hunt down Phaseblade Talasha and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91102] = { id = 91102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Nexus-Edge Hadim (Normal)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "Hunt down Nexus-Edge Hadim and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91103] = { id = 91103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Jo'zolo the Breaker (Normal)", description = "Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! \n\nKill him. Feed his anguish to the defenses of our beloved city.", objectives = "Hunt down Jo'zolo the Breaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91104] = { id = 91104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Zadu, Fist of Nalorakk (Normal)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. \n \nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "Hunt down Zadu, Fist of Nalorakk, and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91105] = { id = 91105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: The Talon of Jan'alai (Normal)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "Hunt down The Talon of Jan'alai and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91106] = { id = 91106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: The Wing of Akil'zon (Normal)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "Hunt down The Wing of Akil'zon and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91107] = { id = 91107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Ranger Swiftglade (Normal)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "Hunt down Ranger Swiftglade and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91108] = { id = 91108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lieutenant Blazewing (Normal)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "Hunt down Lieutenant Blazewing and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91109] = { id = 91109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Petyoll the Razorleaf (Normal)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "Hunt down Petyoll the Razorleaf and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91110] = { id = 91110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lamyne of the Undercroft (Normal)", objectives = "Hunt down Lamyne of the Undercroft and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91111] = { id = 91111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: High Vindicator Vureem (Normal)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "Hunt down High Vindicator Vureem and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91112] = { id = 91112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Crusader Luxia Maxwell (Normal)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "Hunt down Crusader Luxia Maxwell and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91113] = { id = 91113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Praetor Singularis (Normal)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "Hunt down Praetor Singularis and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91114] = { id = 91114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Consul Nebulor (Normal)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic.\n  \nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "Hunt down Consul Nebulor and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91115] = { id = 91115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Executor Kaenius (Normal)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "Hunt down Executor Kaenius and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91116] = { id = 91116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Imperator Enigmalia (Normal)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "Hunt down Imperator Enigmalia and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91117] = { id = 91117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Knight-Errant Bloodshatter (Normal)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n \nHe is starting to become a liability. \n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "Hunt down Knight-Errant Bloodshatter and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91118] = { id = 91118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Vylenna the Defector (Normal)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n\nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "Hunt down Vylenna the Defector and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91119] = { id = 91119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lost Theldrin (Normal)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "Hunt down Lost Theldrin and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91120] = { id = 91120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Neydra the Starving (Normal)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slack her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "Hunt down Neydra the Starving and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91121] = { id = 91121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thornspeaker Edgath (Normal)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "Hunt down Thornspeaker Edgath and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91122] = { id = 91122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thorn-Witch Liset (Normal)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "Hunt down Thorn-Witch Liset and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91123] = { id = 91123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Grothoz, the Burning Shadow (Normal)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "Hunt down Grothoz, the Burning Shadow and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91124] = { id = 91124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Dengzag, the Darkened Blaze (Normal)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "Hunt down Dengzag, the Darkened Blaze and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91136] = { id = 91136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories in Stone", description = "Ja'kul was killed before he could finish my training, but I would recognize his work anywhere! He must have painted this vision stone for me!\n\nThe rutaani will catch on pretty soon that we're up here, and I won't be able to defend myself. Will you keep watch while I journey into the memory he left me?", completion = "Thank you so much, {name}. You gave me a way to say goodbye to my mentor. Now that I have seen what he wanted me to, I can continue my training.\n\nIt means so much that Ja'kul left this here for me. I miss him, but I will honor his memory.", objectives = "Defend Su'meera while she vision walks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91137] = { id = 91137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Light", description = "It seems some of our more adventurous guests have not returned from their hike. Val said he saw a rutaani skulking about earlier, but I was certain he was just trying to add some drama to our day.\n\nThe Lightbloom infiltrated the Sanctum to the north and has been spilling residual issues our way.\n\nOur guests are here to escape the troubles of the world... This all could become a bit too real for them.\n\nIf you'll take care of that situation, I'll make sure Val keeps the guests distracted.", progress = "Did they make it back?", completion = "Tormenting our guests was a step too far.\n\nShe encroached on the sunbath and has paid the price for her actions.\n\nThank you, new friend of the Solaar family!", objectives = "Kill Liya Waterbloom and send the hikers home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91138] = { id = 91138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I am the Creator and Destroyer", description = "Such a small thing, really. And devoid of any of the power T'uure once nurtured. But a relic of inestimable value nonetheless.\n\nDid you know, {class}, that to T'uure, the dark and the light were inseparable aspects of a greater truth?\n\nWhat creates, has the power to destroy in equal measure. Demonstrate this lesson and you will reach a new understanding of yourself, and of the great Naaru whose sacrifice was able to halt the annihilation of an entire planet.", completion = "Ah yes. I can sense the change in you. The growth that comes with meting out death in one hand, while nuturing life in the other.\n\nPerhaps this small token will serve as a reminder of T'uure and his role in Dimensius' ultimate fate.", objectives = "Demonstrate your mastery over life and death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91140] = { id = 91140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Piece of the Past", description = "<This crystalline fragment has lost any luster it once had. Now finally extricated from Dimensius's dread form and in the hands of the devout, a brief glimmer revives in its depths.\n\nPerhaps someone in Tazavesh will know more.>", progress = "What is this? Ah, I see now. You were right to come to me.", completion = "A fragment of the lost naaru T'uure? And lodged in the form of Dimensius?\n\nNow this is something I never thought I'd see.", objectives = "Show the fragment to Om'en in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91142] = { id = 91142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard for the Trusted", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91143] = { id = 91143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Crests", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91145] = { id = 91145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquered Heroes", description = "A domanaar was harrying our back lines. It was... different than the other void beasts--like it was playing rather than fighting. My partner, Callum, led a squad to hunt it down. They never came back.\n\nCallum's an Arathi through and through. He wouldn't fall here--I know it.\n\nCommander Lightblood refused to send a search party. He said there's a difference between personal and important. Well, the Vanguard can have their war, but I'm going after Cal. I know the route he took, but I can't search alone.", completion = "Imperia's beasts swarmed me. I lost track of them.\n\nI shouldn't have left you behind, but seeing that monster control Callum... I'm not losing him. Not while I still breathe.", objectives = "Find Callum Ashvow's squad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91146] = { id = 91146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Light", completion = "She's hurting him, throwing him into fight after fight. We don't have time to search this whole blasted plain.\n\nI can't concentrate. The Void magic here is too chaotic and volatile.", objectives = "Find traces of Callum's Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91147] = { id = 91147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Her Strings", description = "Revik, Riandron, Danna... that domanaar made them kill each other. The creatures here are bound with the same shadowgrafts: the same twisted magic.\n\nIf this is how Imperia controls her victims, we have to find a way to remove it.\n\nRestrain the beasts and I'll attempt to break their bonds. If it's forged by the Void, the Light must be able to overcome it.", completion = "Removing the Shadowgrafts kills them... What good is the Light if it can't save one man?", objectives = "Subdue creatures while Anais removes their Shadowgrafts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91148] = { id = 91148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strung Along", description = "When the Light called, it called both of us. Why? So Callum could die on some void-scarred rock?\n\nI can't think here. All I can picture is Callum bleeding out. Come, we'll return to camp. With his belongings, I should be able to find him. \n\nThen... I don't know. If we can't break the shadowgrafts, we'll subdue him and drag him back to Silvermoon if we must. I'm not losing him.", completion = "I had him. One spear thrust and I could have ended it... but he's still Cal--even with that monster controlling him.\n\n<Anais clutches at ragged cut in her side. Blood and foul Void magic flow from the wound in equal measure.>\n\nLook what chasing after him again got me.", objectives = "Help Knight Anais find and subdue Callum Ashvow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91149] = { id = 91149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bury Me Not", description = "I knew we'd never grow old together, but I thought we'd have more time.\n\n<Anais coughs, blood pooling beneath her. Flecks of the Void shimmer in the spreading crimson.>\n\nDon't worry. I'm not afraid. I promised myself I wouldn't go home without him... wouldn't spend a night in an empty bed. I'm just keeping that promise.\n\nDon't let her have him. Take his tinder box. You'll know what to do.", progress = "My parents always said falling in love with a human would end in heartbreak.\n\n<She doesn't lift her head.>\n\nThere's never enough time, is there?", completion = "I felt it. When you--when he--thank you. Sorry. Getting hard to think.\n\n<She accepts the tinder box and holds it to her chest. Her eyes seem to focus on something you can't see.>\n\nCal...? I'm so tired. Let's go home.\n\n<Anais slumps over, her hand falling away from the wound at her side. She is at peace.>", objectives = "Take Callum's Tinder Box and defeat Imperia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91173] = { id = 91173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flame Burns Eternal", description = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades.\n\nCan we count on your continued support in the battles ahead?", progress = "Ready yourself soldier, the battle is still to come.", completion = "You've bought us a moment of peace.\n\nRest well, but always keep your blade sharp.", objectives = "Complete the Nightfall scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91193] = { id = 91193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Capstone 1 - Unlock" }
quests[91197] = { id = 91197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting Remains", progress = "The domanaar need void-tainted remains to fuel their war effort. Scavenge the area or slay fellow adventurers across Slayer's Rise to obtain this resource.", completion = "Thank you for your contributions.", objectives = "Collect 50 Void-Tainted Remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91203] = { id = 91203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Capstone 2 - Unlock" }
quests[91205] = { id = 91205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ultra Prime Deluxe Turbo-Boost: Powerhouse Challenges", description = "<Undermine has a problem. Here's what we need. An established group, or just a bunch a ya really, ready to help out our pals in Undermine. Help clear out the worst of the competition, and we'll make it worth your time.\n\nComplete the task, and collect a special reward from Consultant Wrexxle outside of the the Dornogal Treasury. Limited time offer. Some restrictions will apply.>", progress = "Yous looks out for us, and we return the favor. Right?", completion = "Thanks, pal. Undermine is a mess right now. We'll take all the help we can get.\n\nAnd hey, a deal's a deal. Here's what we owe.\n\nWe call this the jackpot reward for first time help. Check back again for more work!", objectives = "Defeat any four bosses within The Liberation of Undermine raid on Looking For Raid difficulty or higher, or complete any four Mythic Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91206] = { id = 91206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa Disturbance", description = "Now dat we are tryin' to contact all de loa, my mind turns to Kulzi, de loa of medicine--and the madness that surrounds his shrine.\n\nHis loa speaker, Sij'ta, was a good friend. He healed many war parties of their injuries. But somethin' happened at Kulzi's shrine, and it is full of angry spirits.\n\nDey attack anybody dat tries to get through to dem, and de loa is silent.\n\nPerhaps you can finally reach out to de loa and find his speaker!", completion = "What do you mean, you don't have de medicine? I sent you for it ages ago!\n\nWe must help him... even if de loa won't!", objectives = "Find Loa Speaker Sij'ta at the Shrine of Kulzi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91207] = { id = 91207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Apex Predator" }
quests[91210] = { id = 91210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magister Sunbreaker (Hard)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "Hunt down Magister Sunbreaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
