quests[91214] = { id = 91214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Senior Tinker Ozwold (Hard)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "Hunt down Senior Tinker Ozwold and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
