quests[91218] = { id = 91218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Mordril Shadowfell (Hard)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n \nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "Hunt down Mordril Shadowfell and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
