quests[91220] = { id = 91220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Deliah Gloomsong (Hard)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "Hunt down Deliah Gloomsong and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
