quests[91224] = { id = 91224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Nexus-Edge Hadim (Hard)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "Hunt down Nexus-Edge Hadim and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
