quests[91261] = { id = 91261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Imperator Enigmalia (Nightmare)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "Hunt down Imperator Enigmalia and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91262] = { id = 91262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Knight-Errant Bloodshatter (Nightmare)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n \nHe is starting to become a liability. \n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "Hunt down Knight-Errant Bloodshatter and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91263] = { id = 91263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Vylenna the Defector (Nightmare)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n\nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "Hunt down Vylenna the Defector and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91264] = { id = 91264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lost Theldrin (Nightmare)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "Hunt down Lost Theldrin and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91265] = { id = 91265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Neydra the Starving (Nightmare)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slack her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "Hunt down Neydra the Starving and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91266] = { id = 91266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thornspeaker Edgath (Nightmare)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "Hunt down Thornspeaker Edgath and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91267] = { id = 91267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thorn-Witch Liset (Nightmare)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "Hunt down Thorn-Witch Liset and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91268] = { id = 91268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Grothoz, the Burning Shadow (Nightmare)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "Hunt down Grothoz, the Burning Shadow and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91269] = { id = 91269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Dengzag, the Darkened Blaze (Nightmare)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "Hunt down Dengzag, the Darkened Blaze and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91270] = { id = 91270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Most Important Thing", description = "We will be strong for the Pit!\n\nBut Boletus right. Another thing needed. Must have great name.\n\nBest teams all have good name. Fungus Force. Spore Storm. Cap Clash. And champions, Glow Guard!\n\nAll good names.\n\nWe need amazing name. Best name. So will be best team.\n\nYou help choose?", progress = "Find best name?", completion = "Fungal Fell...owship, ok. Now we ready.\n\nWill run into pit together, shout the Fungal Fello...sip, eh...\n\nCrowd will cheer, then will be new champions!", objectives = "Speak to each of your teammates to choose a name.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91271] = { id = 91271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fish!", description = "There is a deliciously delectable dish that I am dying to share with my guests. We start with just the right fish, then chop it up, drop it in a blend of citrus and our special savory seasonings, and let it bask in the glorious flavors.\n\nIn the shake of a tail feather, it becomes a magical delight for the senses!\n\nWe are the talk of the town, you know. Could you please procure for us the perfect fish?", progress = "I have a great feeling about this one!", completion = "Excellent work, {name}! You have procured a perfectly, pleasingly, plumply proportioned pescatarian prize!\n\nJoyous day!", objectives = "Catch the best fish for the dish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91274] = { id = 91274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Severing the Void", description = "The High Exarch has formed an impressive defensive line. It will hold the Devouring Host's current numbers. But I can see void pylons behind the lines. Those will call forth more Devouring Host and overwhelm the Vanguard of Light.\n\nTheir power is too dangerous for us to destroy directly, but if we can re-activate the sentinels that fell in the initial assault, they could destroy the pylons for us.", progress = "We need to activate all the sentinels if we want to destroy the void pylons.", completion = "With those void pylons destroyed, the Devouring Host has weakened. We may have a chance of winning this.", objectives = "Activate 5 Quel'Danas Sentinels to destroy the Void Pylons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91281] = { id = 91281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight", description = "Locate one of the images of Lady Liadrin that have appeared across Azeroth.", completion = "I am glad you came, {name}. We need your help urgently.", objectives = "Travel to the nearest Image of Lady Liadrin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91283] = { id = 91283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greedy Emissary" }
quests[91284] = { id = 91284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Path Not Yet Chosen", description = "I'm trying to figure out what career path to follow, but I keep second-guessing myself. The Farstriders, the Blood Knights, the Magisters... they all seem so incredible that I can't decide.\n\nI was hoping if I spoke to each and earned a recommendation, I might finally understand where I'm meant to be. Would you help me?", progress = "I really hope I find where I belong...", completion = "Wow... I can't believe I actually got all three recommendations. They all said such kind things, but now I feel even more torn than before!\n\nDo you think... perhaps you could help me choose?", objectives = "Collect Recommendations from the Farstrider, Blood Knight, and Magister trainers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91288] = { id = 91288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of the Hunt", description = "So, you want a Farstrider recommendation? We don't hand those out like festival ribbons.\n\nIf you want to earn it, then you'll need to do what every other recruit does. Bring me lynx pelts, clean and proper.\n\nNo shortcuts, no excuses. Let's see if you've got the spine for it.", progress = "Have you gotten those pelts yet or are you quitting already?", completion = "Well now, look at that. Clean cuts, no mess... maybe the kid's got more fire than I thought.\n\nHere, take this recommendation. Tell them a Farstrider never forgets who earns their place--and to keep their aim sharp. We'll be watching.", objectives = "Gather 8 Invasive Lynx Pelts in the Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91291] = { id = 91291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Blood", description = "Ah, you seek a Blood Knight's recommendation, do you? In that case, you'll need to prove your worth... against me. \n\nOnly those with true strength and honor may join our ranks! Prepare yourself. This won't be a simple challenge, but if you can best me, I'll gladly offer my recommendation!", progress = "Well, what do you think?", completion = "Impressive! You've got more in you than I expected.\n\nYou've proven your strength, honor, and determination--qualities every Blood Knight must possess.\n\nTake this recommendation and wear it with pride. The order is always looking for those who are worthy.", objectives = "Defeat Jesthenis Sunstriker in the Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91292] = { id = 91292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of the Arcane", description = "Ah, you seek a recommendation from a Magister, do you? Very well... but first, you must prove your understanding of the arcane.\n\nGo to the nearby crystals we have for training, extract their energy, and channel it into this staff. Show me that you can harness the arcane, and I will see you worthy of my recommendation.\n\nShould you fail, don't bother returning. My time is too valuable for such trivial matters.", progress = "Well? Is the staff charged, or are you wasting both our lives?", completion = "Hmm, it seems you have a bit more talent than I anticipated.\n\nThis staff is properly charged. Well done, though I'm sure you barely broke a sweat.\n\nTake this recommendation, and remember--the arcane demands respect, not just power.", objectives = "Charge the Arcane Transfer Staff 4 times in Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91301] = { id = 91301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Train Your Protege", description = "I did everything they asked--the trials, the lessons--and they all said I did well... but I still don't know where I truly belong.\n\nEach path felt right in its own way, and now my heart feels pulled in three directions.\n\nPlease... could you help me decide?", completion = "Ah... so the boy has chosen at last. He has heart--too much perhaps.\n\nYes. This will be recorded and honored. You've done more than deliver a message--you've helped shape a life. Thank you.", objectives = "Turn in the chosen recommendation to Instructor Thalendir in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91302] = { id = 91302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abundance: Abundant Grove" }
quests[91314] = { id = 91314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untethered Potential", description = "{class}--I heard you have explored Untethered Space? That place is soaked with pristine void energy. I would like to explore it myself, but the last who have ventured into were consumed by the Void.\n\nI need help with my research. There are Phase-Lost creatures in the Voidscar Cavern that I could use to examine their essence. If you could collect that for me, I would be grateful. \n\nGo carefully.", progress = "Were you able to collect the Phase-Altered essence?", completion = "This will provide a lot to forward my research on Untethered Space. I thank you.\n\nI can't imagine what discoveries we can begin to unravel about K'aresh.", objectives = "Collect 5 Phase-Altered essence in Untethered Space.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91328] = { id = 91328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Ingredients", description = "Our gregarious guests have partaken so much from our stores that we are running dangerously low of our special Solaarian sintalia.\n\nThe rich taste of belanise, with its intoxicating scent, contrasts perfectly with the sharp tartness of the local berries. Carefully prepared then soaked in our special blend of spirits, then served--it's to die for!\n\nJust between us, if the berries are not handled just right, the infusion can be quite deadly. Otherwise... delicious, invigorating, purifying, glorious!", progress = "Are you gathering carefully?", completion = "Magic! Perfection! You could not be more skilled if I had wished you into existence.\n\nThat is an interesting thought. Could I have?", objectives = "Collect 6 Belanise Blossoms and 5 Sinara Berries for the Solaarian Sintalia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91339] = { id = 91339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smothered in the Crib", description = "I summoned my first imp in a dirty, haze-filled lounge beneath Murder Row after a dozen failed attempts. Each time, I reached further for what made so-called greater powers submit to mortals. I finally managed it after wetting my hands with the hot blood of a young rabbit. Bloodthistle never satisfied me again.\n\nI have matured my technique since then. Seek the whelps of these beasts. Siphon their energy into my reliquary of darkness. From their sacrifice, we will draw the power to defeat Kalgorg.", completion = "This too is the natural order of things.", objectives = "Drain 9 juvenile wildlife with the Reliquary of Darkness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91340] = { id = 91340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Violence's Sake", description = "Like many warlocks, I bind my demons with terms of a contract. I should have realized the Void and violence of this world could affect the rules I took for granted. Kalgorg used that power to break its bindings and end our arrangement. \n\nWhen we confront Kalgorg, the scent of blood and violence must be upon us. Slay the beasts you find to demonstrate to Kalgorg we are willing to do the same to it. Control over the Void is found and lost within the blink of an eye.", completion = "<Lucia looks you over and then rewards you with a cruel smile.>\n\nSplendid. You are as capable as you look.", objectives = "Kill wildlife on the surface of the Den of Predaxas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91341] = { id = 91341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlimited", description = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you.\n\nKalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain, but we must proceed and claim the power within. Fill the reliquary to the brim. \n\nI know not what to expect from my voidwalker. We will need all the power we can manage.", progress = "The trail of carnage it left behind... I'm almost proud.", completion = "Kalgorg waits before us. Now we spend the power you've been collecting reclaim it.", objectives = "Gather Void Power within the Lair of Predaxas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91342] = { id = 91342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You Want It Done Right", description = "With all the problems facing Eversong, the Farstriders have their hands full!\n\nI'm a capable arcanist. I've always admired the Farstriders--why not lend my talents to their cause? They do so much work by hand, when a bit of magic would allow them so much more time for adventuring!\n\nAlas, my enchanted broom idea has not quite gone as I'd hoped. They're so ornery, they end up attacking the recruits instead of cleaning!\n\nPerhaps this is a problem for elbow grease after all.", progress = "Captain Dawnrunner warned me about trying to solve all my problems with magic... Clearly I have much yet to learn.", completion = "The sweeping will still need to get done, but at least now no one will be attacked.", objectives = "Slay 8 Ornery Sweepers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91343] = { id = 91343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambition's Reward", description = "You have filled the reliquary with power I can draw on. Now, we reap the reward of our preparations.\n\nKalgorg waits just ahead, draining the beast that once made this cave its lair. Weaken Kalgorg, and I will bind it as I first did years ago.", completion = "Kalgorg consumed much of the Void energy within that cave, which means its influence is less likely to overwhelm my kin. I suppose some good was done.\n\nI must pay Kalgorg the slightest compliment. Were I a subdued void beast, I'd also try to escape. For that, it has my respect.\n\n<Lucia turns to Kalgorg with a sharp smile.>", objectives = "Subdue Kalgorg the Unshackled.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91345] = { id = 91345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the North Tower", description = "Ranger Valsarin is a chef at Farstrider Hold. He's decent in a kitchen, but his passion is field cooking.\n\nThere was a time when you could wander any path in Eversong and find the ingredients for a good meal. A Farstrider's dream! With enough hard work, we can help the forest recover, and it starts with rehabilitating the soil.\n\nMeet Valsarin at the North Tower and he can tell you more.", completion = "Hope you like getting your hands dirty.", objectives = "Meet Ranger Valsarin at the North Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91346] = { id = 91346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplicants to the Goddess", description = "We have long tended to the roots with the help of the creatures who live and grow here. Think of it as a symbiotic relationship from which we, the creatures, and the roots all benefit. That said, my partner Riverscale isn't contributing very much lately!\n\nPlease help me find a way to motivate him again.\n\nFirst, you must cleanse off the essence of the outside. Cleanse yourself in the waters of Har'kuai.", completion = "This may seem inconsequential, but it's all a part of the process.", objectives = "Cleanse yourself in the Waters of Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91347] = { id = 91347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strider Stampede", description = "It's hard to believe this used to be the Dead Scar.\n\nUp here, close to the city, the land has almost completely recovered. Which is good, because we've got a lot of mouths to feed.\n\nHawkstriders are the perfect helpers for preparing the soil. Their tough claws can easily spread seeds and squash bugs!\n\nMeet me down in the Tranquil Repose and I'll saddle one up for you.", progress = "Nothing like planting seeds.", completion = "I don't know what to make of those big blooms... but whatever we're doing, the land seems pleased.", objectives = "Mount up the Saddled Hawkstrider and prepare the Tranquil Repose for gardening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91348] = { id = 91348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See a Mana 'bout a Wyrm", description = "Mana wyrms may not be as glamorous as lynxes or hawkstriders, but they're crucial to keeping magic flowing through the forest.\n\nThey congregate on the ley lines to molt, but sometimes they get a little agitated. And we have to help them out! Aggressively!\n\nI've set up some ley channels to get things started. Find wyrms that look like they could use a little help, and beat them up until they shed their arcane carapace. Don't worry--all that mana returns to the forest eventually!", progress = "Don't worry! They bounce right back.", completion = "Another successful molt... We'll be out here in a few weeks to do it all again!", objectives = "Aggressively assist 8 Agitated Wyrms with their molting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91349] = { id = 91349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Part of the Woods", description = "Much of the forest has recovered, but to the south... Everything that Eversong has faced--the Scourge, the fel, and now the Twilight's Blade--all that magic leeches into the soil. It builds up in the creatures until they're completely overwhelmed...\n\nMy instruments can detect corruption in these animals. We can cull the ones that are too far gone and save the ones that aren't. It isn't fun... but it's for the good of Eversong!", progress = "It's hard work, but it will bring peace eventually.", completion = "These poor cubs... They survived only by the grace of that strange magic!\n\nI know better than to believe in the old tales... but what else could it be?", objectives = "Test 8 creatures for corruption, and deal with the consequences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91350] = { id = 91350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Real Assignment", description = "Captain Dawnrunner was supposed to check on the Enclave and then meet us here. She's as capable a ranger as any! It's a bad sign if she's been detained.\n\nFarstrider Enclave is usually where they do wilderness training. With all the trouble however, everyone's been dispatched elsewhere. She could be up there alone, in serious danger!\n\nThere's no time to lose. I'm going to save my Captain and prove myself as a Farstrider!", completion = "This is what happens when there's no one around to sweep up!\n\nEveryone wants to adventure, but no one wants to sweep.", objectives = "Find Captain Dawnrunner at Farstrider Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91359] = { id = 91359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Lashers B Gone", description = "We are blessed to live in Harandar, but this is also our responsibility. The roots of the World Trees wind through these lands. We tend them, and they thrive. That is why it is so important for Riverscale to be back on duty.\n\nWe need to keep these grounds clear of these fungal lashers before they leach off the roots. As a plus, Riverscale really loves lasher fronds. Can you find and bring some back for him?", progress = "It's important that we keep the lashers from sapping important nutrients from the World Tree.\n\n...and I like spoiling my obstinate little boy.", completion = "I wish that I didn't have the laziest helper in the history of helpers, but such is life!\n\nIf his favorite treats won't get him up, nothing will.", objectives = "Collect 6 Harmonious Fronds in the outskirts of Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91360] = { id = 91360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weeding Out the Unwanted", description = "The roots of the World Trees are infused with both nutrients and the magic of Harandar. As the large vessels that they are, they will draw to them unwanted fauna and flora. Some of them are harmless, but we want to keep the roots clear.\n\nHaranir can often be allergic to the green weeds that flourish beside the roots of the World Trees. If you rip them out by the root, you would be saving us a lot of time--and hives!", completion = "You're a weed-pulling, no-rash juggernaut!", objectives = "Pull 8 Allergenic Weeds in the outskirts of Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91361] = { id = 91361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back on Duty?", description = "Finally! I knew the little guy could do it.\n\nNo, that is a bald-faced lie. If this grovecrawler could somehow find a way back into his cocoon, he would already be there.\n\n<Cyenna sighs.>\n\nHis second favorite treat is the potatoad. If that doesn't work, his third favorite treat is the petalwing. That should get him back onto his mite-hunting duties.\n\n...I have the backbone of a wet frond.", completion = "I knew you could do it, Riverscale! Who's a good grovecrawler? Who's the best crawler of them all?\n\nWho's a big strong grovecrawler who knows how to teach strangers how to care for World Trees?\n\n<Cyenna looks up at you.>\n\nYou knocked him out of his laziness, {name}. I can't thank you enough for your help.", objectives = "Help Riverscale gain his confidence by killing 8 Potatoads and Petalwings by the outskirts of Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91363] = { id = 91363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvest of Darkness", description = "You... make yourself useful.\n\nAs a master of terrible beasts, it is my job to mold these hatchlings into dreaded beasts. I pit them against each other and they grow ever more violent.\n\nBut the elves here insist that I will yield better results with just a bit of... tender loving care. Let us put this to the test.\n\nThis runt is Fidoficus. You will show him tenderness and affection, and then we will see how ferocious he becomes.\n\nCollect some delicious dietary treats for him and return to me.", progress = "These ingredients will make for a highly nutritious and equally delectable meal.", completion = "Fidoficus will be renowned for his ferocity.\n\nI can see the violence growing in him.\n\nOne day, he will be a worthy pet for a domanaar such as myself.", objectives = "Collect 10 Void-Infused Morsels and 6 Glaring Glowcaps outside of the Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91375] = { id = 91375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silence at Fungara Village", description = "Fungara Village has been silent for some time now.\n\nWe've largely been occupied with the Lightbloom and the threat it presents, so we haven't had time to check in on the fungarians to the east. Usually, they are rowdy yet manageable... but it's rare that they go completely silent.\n\nI am going to investigate. If you wish to prove yourself an ally, you would do well to join me.", completion = "Normally, I would refuse the intervention of an outsider without a second thought... but given the situation, perhaps you can be of some help.", objectives = "Seek Ghikal outside of Fungara Village in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91376] = { id = 91376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Monsters", description = "When I sent a request for aid from Har'alnor, I did not expect them to send me an outsider. No matter.\n\nThe denizens of Fungara Village have gone quiet. Normally, I would be thrilled: they're horribly screechy. But the way they are shambling about... it is like they have forgotten that they yet live.\n\n<Ghikal shudders.>\n\nI tried to get close, but they attacked me on sight.\n\nI will need samples of their flesh. Go and bring them to me, so I can see what has happened here.", progress = "I do not know what is going on, but to err on the side of caution... do not let them bite you, hrm? Whatever plagues them may be infectious.", completion = "Goddess forfend. This is not fungarian flesh at all.\n\nWhat ARE they?", objectives = "Collect 10 samples of Strange Mycelium from the former denizens of Fungara Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91377] = { id = 91377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn of the Dead", description = "It is obvious that something terrible has happened in the village. I can see the corpses of their largest specimens strewn across the southern reaches from here, but something is off about them too. Fungarians don't usually just leave the corpses of their kin lying about.\n\nAnd though I am watching from afar, I swear that some of them are... twitching.\n\nInvestigate. Find out what you can, and report back to me.", completion = "This is so much worse than I thought.\n\nWe have to find the source of this and destroy it before it infects something bigger and more dangerous than a fungarian.", objectives = "Investigate 5 Blooming Corpses in Fungara Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91378] = { id = 91378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Are Legend", description = "Whatever these things are, they're not fungarians. Not anymore. \n\nHar'alnor has enough to worry about with the Lightbloom as it is. It cannot afford to be trapped between its forces and these... things.\n\nDo what must be done. Destroy as many of them as you can.", progress = "Do not feel regret. These things are not alive anymore. Not in any way that matters.", completion = "You are quite the accomplished slayer of aberrations. Perhaps you should consider a vocation in monster-hunting.", objectives = "Kill 15 Decanimated fungarians in the northern reaches of Fungara Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91379] = { id = 91379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decayed Land", description = "As far as I can tell, these fungarians are all already dead. Something is animating their corpses from within, like puppets attached to unseen vines.\n\nThis fungal matter that's infesting them must be coming from somewhere... and judging from the size of the ones further north, we'll find plenty of it there. Find it, get rid of it, but for Aln'hara's sake don't breathe it in.", completion = "We've culled the worst of the growths to the north... but there are smaller ones already beginning to sprout. Where are they coming from?\n\nThere must be a source, and we'll have to find it if we mean to solve this thing.", objectives = "Destroy 8 growths of Fruiting Mycelium in Fungara Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91380] = { id = 91380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belly of the Beast", description = "I normally raise my beasts on a diet of raw, bloody carcasses and souls ripped asunder by the Void.\n\nBut we shall try your mortal ways.\n\nI hear you... cook? And that makes the treat better?\n\nDo this. Then, take him on a walk around the Howling Ridge. Even I know exercise is good for digestion.\n\nOnly the most ferocious of creatures is worthy of serving me. I hope neither you nor Fido disappoint me.", completion = "Is the beast's savagery growing?\n\nI'm sure I will begin to hear of his violence from those around the Howling Ridge.", objectives = "Feed and walk Fidoficus around the Howling Ridge to promote its growth and savagery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91381] = { id = 91381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reticent Evil", description = "I do not understand. We've searched high and low, north and south. Everywhere we go, we find animated corpses and small fruiting fungus, but where is the central body? Where is--\n\nOh, goddess. Of course.\n\nThe water, {class}. Check the water.", completion = "It is done, then.\n\nYou did well to survive untainted. The wilds are a dangerous place, and survival is never a guarantee.\n\nNow go. I must remain and ensure that these abominations cannot spread any further.", objectives = "Destroy the Agericus Decanimatus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91382] = { id = 91382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mighty and Superior", description = "The beast is fed and exercised. Imagine, mortal... one day his maw will grow to fit you inside it a thousand times over. \n\nNow, we will test his potential for true violence. \n\nThere is a beast that has laid claim to a den south of the Howling Ridge. \n\nFidoficus trusts you now. Go with him and bear witness to his might.", progress = "Fidoficus has grown fearsome, and perhaps you have claim to some of his growth.", completion = "Fidoficus will grow so terribly large, that it is he who will be walking you. \n\nOnly then will he be worthy of joining me as my attack behemoth.", objectives = "Bear witness to Fidoficus's savagery as it slays Den-Gorger Zitoc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91383] = { id = 91383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidy Up", description = "Captain Dawnrunner is fine, thank the sun. The only danger was... we didn't keep up on our chores.\n\nIt's not heroic, it's not romantic, but we can't go on with Farstrider Enclave in this state. The rangers here are overwhelmed. We can all pitch in to help them get it cleaned up again.\n\nI can't believe it all comes back to sweeping. That's what being a Farstrider is really about.", completion = "My rangers are earning their keep today, that's for certain.", objectives = "Clear out 5 Messy Nests and sweep up 5 Dusty Webs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91384] = { id = 91384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovery Mission", description = "We've been deploying Farstriders across the forest to fight the Amani, the Lightbloom, the Void... but for all our heroics, there's no one left to tend to the wildlife! Or maintain the building! Or keep track of supplies!\n\nAnd now our beloved Enclave looks like a hawkstrider pen. I've had enough!\n\nI may not be able to help, but I trust you all can gather anything that was taken and get this place looking respectable again.", progress = "If we want to be of any use to the rest of Eversong, first we must pick up after ourselves.", completion = "This is a good start. All it takes is a handful of us putting in a little effort.", objectives = "Retrieve 12 Scattered Supplies from around Farstrider Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91385] = { id = 91385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ranger's Spirit", description = "Taemin has proved himself as capable as any Farstrider today. But I'm afraid he might not see it that way.\n\nHe came to us with such lofty ideas about the rangers--all those swashbuckling adventure stories, all the romantic old legends. But at the end of the day, being a ranger is mostly... chores. Difficult, boring, important chores.\n\nWhy don't you go talk to him, and make sure he's not too disappointed?", progress = "The beauty of the forest? It never gets old.", completion = "The legends are real... Eversong must be pleased with us!", objectives = "Find Recruit Taemin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91386] = { id = 91386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mad to Measure", description = "These... tourists! These uncultured, ungrateful slobs!\n\nThis Vanguard of Light has brought a lot of business to Silvermoon, to be certain. But none of them actually appreciate what Thalassian craftsmanship means. They have no respect for the elven arts--they just want shiny, glittery souvenirs!\n\nI am no spring runner dancing for their amusement... but I can hardly turn them away, can I? Perhaps an assistant would make this atrocious task easier.", progress = "If only a single soul among these brutes showed any appreciation... alas, it seems even this small ask is too great.", completion = "All right... but only because I'm curious about the craftsmanship.\n\nIt'll take more than a little politeness to change my mind about these pernicious paladins.", objectives = "Assist Solwin Brightstitch with making clothes for Pushy Paladins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91388] = { id = 91388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncommon Threads", description = "Our patron--Gaari, I suppose--should count himself lucky. These mana wyrms produce the finest silk in Eversong. I know Magisters who would kill to have a robe trimmed in this, and yet here we are, using it for a mending job. Ah well.\n\nOnce the wyrms have eaten their fill of arcane energy, you can siphon the silk from them onto these bobbins.\n\nIf they are reluctant to release their silk, you may have to, ah... beat it out of them. But I've been assured it's entirely ethical.", progress = "This is the easy part, of course.", completion = "Ah... beautiful, glittering manasilk. So ripe with potential.", objectives = "Siphon 8 Full Bobbins of Manasilk from weakened wyrms in the North Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91389] = { id = 91389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clothes Make the Man", description = "It is not merely the material that makes an arcanoweave cloak so fine, but the weaving process itself.\n\nTo mend one, particularly one that has built up so much history and latent arcane energy... I am about to embark on a very dangerous bit of tailoring indeed. Finally, a real testament to my skills.\n\nI am excited. I hope nothing explodes. Meet me inside when you're prepared.", completion = "It is a thing of beauty... I am glad to know it is in the hands of someone who loves it so.", objectives = "Meet Solwin inside, then fend off any manifestations as he mends the cloak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91390] = { id = 91390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: What Remains of a Temple Broken" }
quests[91391] = { id = 91391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Scouting", description = "When the Alliance originally fought the Horde here, Kurdran served as a scout. He's still an excellent one. He took his gryphon to Blackrock Mountain to see what kind of forces we may be dealing with there.\n\nMeet up with him and see what kind of trouble you can cause.", completion = "Arator, {name}--thanks fer coming. Plenty o' Dark Horde in there.", objectives = "Meet Kurdran at Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91392] = { id = 91392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greedy Emissary" }
quests[91398] = { id = 91398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomes of Terror", description = "Knowledge is power, and de ogres been reading.\n\nBring me dey tomes so dey never grow dis powah again.", progress = "Get me de tomes.", completion = "Thank ya. Dese are going straight into de fire.", objectives = "Kill ogres in Atal'Kaldan and collect 4 tomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91399] = { id = 91399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of the Void", description = "De void elementals have one use.\n\nDe dust dey drop is useful for shadow magic rituals.\n\nCollect some for our tribe.", progress = "Don't worry, we been doin' dese rituals for centuries.", completion = "Our hunters gonna make good use of de powder. Thank ya.", objectives = "Kill void elementals and collect their ashes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91400] = { id = 91400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blades of the Fallen", description = "After de battle we left a lot of our weapons behind.\n\nPlease go collect dem so de Twilight's Blade doesn't get dem.", completion = "Thanks for collecting dem. Now our foes won't get de advantage of fine Amani crafting.", objectives = "Collect 12 Amani weapons from Atal'Kaldan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91401] = { id = 91401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead by Dusk", description = "De Twilight's Blade cultists have de audacity to try and take back our temple. Kill de peons and bring me their femurs.", progress = "Why femurs? None of ya business.", completion = "I got a plan for de bones. Thanks.", objectives = "Collect 20 femurs from Twilight's Blade cultists in Atal'Kaldan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91402] = { id = 91402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ultra Deadly Ultradon", description = "I saw some of de void elementals doing a sketchy ritual in de center of the battlefield. It looked like dey were summoning some void creatures.\n\nMake sure whatever dey summon is dealt with.", completion = "Never seen one of dem before and hope I don't see dem again. Nicely done.", objectives = "Kill the Eminent Ultradon in the center of Atal'Kaldan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91403] = { id = 91403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probable Paralytic", description = "Halazzi says dat de Vilebranch have made a new venom dat para... parliz--makes its victims not move--so they can drag them off to be sacrificed. He says it's frog venom.\n\nI said that doesn't make sense. Frogs are poison, right? Halazzi said frogs are normally poisonous, not venomous. But these have sharp horn bits on them, so maybe they have venom! I didn't know frogs could have venom, did you?\n\nLet's find out if these do--then de Witherbark can make an anti-venom!", progress = "Halazzi says venomous is when dey bite or stab you, and poisonous is when you bite or eat dem! Isn't dat interestin'?", completion = "Look at all de samples you found! De chief will know who can make anti-venom for sure.", objectives = "Collect 8 Venomous Horns from Horned Frogs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91404] = { id = 91404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Vile Venom", description = "De Vilebranch are cookin' up more bad things. You should go to de source and make dem stop!\n\nHalazzi has smelled their venom-mixin' place someplace to de southeast, and he thinks it's more den just frog venom.\n\n...Oh, Halazzi also said to bring back some kind of huge fang. Frogs don't have fangs, though. Well, find it anyway!", progress = "Did you look for de big fang?", completion = "Hey, dat's a spider fang. Dat must have been one huge spider!", objectives = "Kill Venomhexxer Raxxis and find the fang Tobui described.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91405] = { id = 91405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Validating the Venom", description = "This means there are both frog and spider venoms in de mixtures. Halazzi says he senses somebody beseeched Shadra with dat fang. Dey must be a really big spider if their fang is dat big!\n\nHalazzi doesn't like that de Vilebranch had it. I can tell. He's unhappy. His ears get all flat like de wings of a kite.\n\nSo we gotta help out. Take de samples and de fang to de Witherbark Chief. We Witherbark have alchemists dat can brew anti-venoms for both spiders and frogs.", completion = "De Vilebranch are de ones doin' somethin' with Shadra?\n\nCould de spiders be workin' against de Witherbark? This doesn't make sense.", objectives = "Speak to the Witherbark Chief and locate an anti-venom alchemist in the village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91406] = { id = 91406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Far from the Hinterlands", description = "As a Torntusk of de Revantusk tribe, I am cautious of Witherbark because of our history with dem in de Hinterlands. My family moved here because of dem.\n\nThe Witherbark here in Zul'Aman seem to respect us, but de Witherbark I remember in de Hinterlands killed and backstabbed their allies for power.\n\nThey worshipped de spider loa, Shadra.\n\nWhen de Hinterlands's Witherbark temple Shadra'Alor fell, de Witherbark must have fled somewhere. Look around for evidence of Hinterlands Witherbark and of Shadra.", completion = "All de places dey mentioned are right next door to Shadra'Alor! Dey probably worshipped Shadra.\n\nWe can't trust dem. Dey are like de venoms dey use. Dey will poison de rest of de tribe against de Revatusk--against us all!", objectives = "Investigate the Witherbark from the Hinterlands for signs of Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91407] = { id = 91407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of the Loa", description = "I lost friends to venoms made from Shadra's spiders in de Hinterlands. I gotta know if Shadra's lurkin' around here, twistin' de minds of these Witherbark. No Revantusk will be safe in Zul'Aman with Shadra-worshippin' Witherbark around!\n\nMaybe I seem paranoid, but I have my reasons. And you have Halazzi's ear. You could ask him to reveal to you any hidden spiders, yes? I know those long ears can hear dem skitterin'!\n\nThere is a shrine behind me. Stand in front of it and see if he'll grant you a boon.", completion = "De spiders fled? I thought dey would put up more of a fight. And you said dey were small? Hm.\n\nWell, it doesn't matter. Halazzi has set us on this hunt now. We need to see it through.", objectives = "Find evidence of Shadra in the Witherbark Bluffs with Halazzi's aid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91408] = { id = 91408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Shadra", description = "We will untangle dis mess about Witherbark and Vilebranch soon enough. De loa Shadra and her schemes must be our first priority.\n\nI watched the spiders run in terror from you, and somethin' struck me. De spiders are not just running in panic--they're going somewhere... somewhere dey feel safe, and even I can see dem now. \n\nDey are not hiding anymore. Dey are on de run! Our hunt continues.\n\nLet's follow dem.", progress = "Where dis trail leads, we follow.", completion = "Let's hear him out, but keep your hand on your weapon.", objectives = "Follow the spiders to find where they lead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91409] = { id = 91409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreaming of Spiders", description = "There are three relics of Shadra. I only had two. I had de fang in de village and de eye hidden here. Dey musta stolen de fang somehow, then came for de eye!\n\nWe never had de Shell of Shadra--it was lost when we left Shadra'Alor. It's possible de Vilebranch have de shell.\n\nDe fang and de eye should let us talk to Shadra briefly, even if we lack de last ritual relic to summon her.\n\nCome with me. I will show you how.", progress = "De two artifacts should be enough to speak to a vision of Shadra.", completion = "This is de Shadra I remember from Shadra'Alor. She will assist us if we help her.\n\nShe keeps her promises.", objectives = "Attempt the ritual with the fang and eye to speak to Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91410] = { id = 91410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shared Loa", description = "De Witherbark Chief knows many of us came from de Hinterlands with our worship of Shadra'Alor, but believed Shadra was long dead.\n\nWe should let him know how Halazzi helped us to find and restore Shadra, and of Shadra's presence in de Witherbark crypt. He also must learn of de rapport with de Revantusk.\n\nI will stay with Shadra for now. Will you carry de message?", completion = "With Shadra aligned with us against de Vilebranch, we will punish dem grievously for their evil acts.", objectives = "Speak to the Witherbark Chief about Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91411] = { id = 91411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisara Caverns: Deep in Maisara", description = "Shadra has asked dat we recover de third piece of Mixer Jamanga's ritual, de Shell of Shadra. With it, maybe we can bring her back.\n\nShe recognized both de Witherbark and Revantusk as her allies. I felt her approval upon all of us. I believe this is de right choice.\n\nHalazzi set us on dis path, and we each got our roles to see it through. Gather your allies and go into Maisara Caverns! I would expect one of their leaders to hold de shell. Kill dem and take it back.", progress = "I think dat Shadra will honor her word.", completion = "I can't imagine dat was easy. Halazzi must have blessed your hunt.", objectives = "Recover the Shell of Shadra from within Maisara Caverns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91412] = { id = 91412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Venom Queen", description = "It is time to bring Shadra to her proper place as a loa of de Witherbark and Revantusk. She will be small at first, but one day could be great like Halazzi and Nalorakk!\n\nEven a small loa will be a good ally against de Vilebranch venoms. She is de Loa of Spies, and will block their thievery of our people and relics, just as Halazzi hides them in the mists.\n\nHold de Shell of Shadra in de center of de room, and we will call de loa to us!", progress = "This is more than de return of a loa--it is a bridge between tribes.", completion = "This journey has been... eye-opening. \n\nHad you asked me at the start if we would be allies with Shadra, I would have laughed in your face!", objectives = "Follow Mixer Jamanga's ritual to restore Shadra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91413] = { id = 91413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Twilight Oath's End", description = "<The ancient runes on the page seem to twist under your gaze. Their power seems to be rapidly fading.>\n\n<Ve'nari would be interested in this.>", completion = "Salhadaar cheated death to revive Dimensius, and cheated death again by escaping your wrath.\n\n<Ve'nari pauses for a moment.>\n\nA pity he escaped, but the All-Devouring has perished. Thank you.", objectives = "Bring the Mark of the Twilight Oath to Ve'nari in the Oasis on K'aresh.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91419] = { id = 91419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Dominance" }
quests[91420] = { id = 91420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swap Meet", description = "<The mysterious mineral thrums in your hand. Someone in Tazavesh will find a use for this. Look around the Veiled Market for an interested party.>", completion = "<Om'myuz takes a closer look at the ore.>\n\nThat is quite the intriguing rock you've found. I would like to inspect it further, and any others you find. What say you to a trade?\n\nOther Cartel Om members in the Veiled Market may also be interested in trading wares, should you come across them.", objectives = "Bring your discovery to Om'myuz in Tazavesh.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91426] = { id = 91426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The People's Champion", description = "I think we've done all we can for the moment, {name}. Let's return to the muster point.", objectives = "Return to the muster point with Arator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91427] = { id = 91427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mausoloa Desecrations!" }
quests[91429] = { id = 91429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mausoloa Sarcophagi!" }
quests[91430] = { id = 91430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runaway Limbs!" }
quests[91437] = { id = 91437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call for Participants", description = "<You find a scroll in your pocket that was not there before.>\n\nHey, it's Nostwin! You doing anything? No? Come help us do TIME SCIENCE!\n\nEternus can tell you more.\n\nOkay thanks bye!", sourceObjective = "Speak with Eternus at the Infinite Bazaar near Dalaran.", completion = "Excellent timing, {name}. Now the research can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[91438] = { id = 91438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Heroic Worldly Deeds", description = "All across the Broken Isles there are people in need. They search for hope but are hard pressed to find any. You can be that hope.\n\nSeek out those in peril in the Broken Isles and be the champion they so desperately need.\n\nIt is through such acts that legends are made.", completion = "A single heroic act can turn the tide. A single whisper of hope can turn back despair. This is what gives legends their power.", objectives = "Complete 3 world quests in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91439] = { id = 91439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Heroic Invasion Points", description = "The Legion does not fight conventionally. They deceive, manipulate, and undermine their opposition at every turn.\n\nThere are no battle lines against the Legion. They will open rifts at a weak point and then spill out of it sowing death and destruction. When they invade, it is on their terms.\n\nHowever, this strategy is not invincible. Potent champions, able to move and react swiftly, can stop these invasions at their source. Stop the Legion Invasion. Show people that the Legion can be defeated.", completion = "The power you and your artifact possess were able to halt a Legion invasion. But was it you, or the artifact you wield, that is responsible? On that I will require more information.", objectives = "Complete a Legion invasion point in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91440] = { id = 91440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Hero of the Broken Isles", description = "Heroic deeds are a matter of perspective. What may seem trivial to a mighty hero such as you, could mean the world to another.\n\nSeek out those in need and aid them in whatever task they deem important. In doing so your legend will grow.", completion = "Your name is on the minds of the people, and is shared around the fire. The greater your legend becomes, the more powerful your name will be. But does the power of one's name eclipse that of the artifact they wield? This is the burning question.", objectives = "Complete 5 quests in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91441] = { id = 91441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Heroic Greater Invasion Points", description = "Once the Legion has sown confusion and chaos, then they will begin their real assault. Huge invasion rifts will open and the Legion will march forth in great numbers. The defenders, scattered to protect against smaller rifts, will lack sufficient strength anywhere to stop them.\n\nThat is when champions like you are most needed.\n\nSeek out one of the Legion's major invasions and throw everything you have at it. \n\nShow the people that with enough determination you can cancel the apocalypse.", completion = "Just as I predicted. You were able to stop a massive Legion invasion. It was not you, or your artifact that did this. Rather it was the combination of both that won the day.", objectives = "Complete a greater Legion invasion point in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91442] = { id = 91442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eco-Dome Al'dani", description = "We have received word from Ve'nari that the Wastelanders continue to stand in the way of progress on K'aresh. They threaten the most promising eco-dome.\n\nThe restoration directive of K'aresh must not be interrupted.\n\nPut an end to these inefficiencies.", progress = "Have you put an end to their efforts?", completion = "This is a promising beginning to our new relationship with K'aresh.\n\nGood work, outlander.", objectives = "Biergoth wants you to confront Soul-Scribe within Eco-Dome Al'Dani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91443] = { id = 91443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Rare", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare study, so focus on fighting rare opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 4 rare enemies in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91444] = { id = 91444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Elite", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be an elite study, so focus on fighting elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 5 elite enemies in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91445] = { id = 91445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Comprehensive", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a comprehensive study, so feel free to fight whatever you wish so that we can get a baseline understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 75 enemies in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91446] = { id = 91446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Rare Elites", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare elite study, so focus on fighting rare elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill a rare elite enemy in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91447] = { id = 91447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Demonology", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a demonology study, so focus on fighting demonic opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 30 demons in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91448] = { id = 91448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Heroic Terrors of the Broken Isles", description = "It is time to put both you and your artifact to the test.\n\nSeek out a Terror of the Broken Isles and defeat them.\n\nI am certain that, no matter the outcome, you will provide us with much to think about. I will be watching with great interest.", completion = "A fascinating outcome, {name}. This will shed some much needed light on our research.", objectives = "Kill a world boss in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91449] = { id = 91449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Advanced Combat Studies, Empowerment", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of the empowered enemies in the experimental, fractured timeline. We need to understand how your abilities fare in the face of terrifying change. \n\nAnd remember, this is for the greater good.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 10 empowered enemies in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91450] = { id = 91450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Ready Now", completion = "Already trained for the ring?\n\nWas very fast. Much impress.\n\nWhat is team's name?\n\nNeed name to shout when run into the Pit.\n\nAnd crowd needs name to shout when you beat other teams.\n\nOr if...", objectives = "Return to the Grudge Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91451] = { id = 91451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk Market", description = "<The mysterious plant thrums in your hand. Someone in Tazavesh will know what to do with it. Look around the Veiled Market for an interested party.>", completion = "<Om'mit turns the plant over in his hands.>\n\nA void-infused stalk from a dead wasteland? This is utterly useless to you. In fact, let me take it off your hands in exchange for plants with more... familiar properties.\n\nOther Cartel Om members in the Veiled Market may also be interested in trading wares, should you come across them.", objectives = "Bring your discovery to Om'mit in Tazavesh.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91452] = { id = 91452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Range of Knowledge", description = "I've always dreamed of being a Farstrider--the adventure! The romance! The beauty of nature! When they put out a call for help, I knew I had to join.\n\nCaptain Dawnrunner assigned me to the library initially, but with everything going on, we all have to be flexible.\n\nI don't mind, but I had hoped to collect all the overdue books before being sent on a real assignment. If you find any, would you bring them to the library for me?\n\nAnd feel free to give them a read! There are some interesting volumes!", progress = "It really takes everyone to get through times like these.", completion = "It might seem like a small thing, but the small things add up.", objectives = "Retrieve 3 overdue books from around Farstrider Hold and return them to the library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91454] = { id = 91454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase-Lost Adventurer", description = "Covered in slime and saliva, the journal bears a partial entry of a previous Phase Diver.\n\n<Day 27\n\nUntethered Space is much more vast than I expected, with monsters stronger than I have seen on K'aresh. \n\nThere is a nearby cave I will explore tomorrow. It is brimming with Phase-Altered Essence. This could bode useful for better understanding the ecology out here.>\n\nResearcher Essarae would be very interested in this.", completion = "<Essarae flips to a random page in the journal.>\n\nThis is brimming with knowledge of Untethered Space. I would like to read it further. \n\nThank you for aiding my research.", objectives = "Take the journal to Researcher Essarae in Shan'dorah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91457] = { id = 91457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abundance: Watha'nan Crypts" }
quests[91458] = { id = 91458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Endurance Hunter" }
quests[91459] = { id = 91459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", completion = "That certainly qualifies as high-ranking, {name}! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91460] = { id = 91460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", completion = "That certainly qualifies as high-ranking, {name}! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Heroic difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91461] = { id = 91461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", completion = "That certainly qualifies as high-ranking, {name}! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91462] = { id = 91462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Central Tower", description = "Ranger Asterae is one of our veterinarians. She usually cares for our lynxes, but the mana wyrm molt is too crucial to the health of the forest to go unmonitored.\n\nThe wyrms regulate the flow of magic from the ley lines to the rest of the woods. When the ley lines were disrupted, so was their molting season. It's not so dire as it once was, but they still need help from time to time.\n\nMeet Asterae at the Central Tower. She can tell you more.", completion = "It's a good thing we came. There are more mana wyrms here than usual.", objectives = "Meet Ranger Asterae at the Central Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91463] = { id = 91463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the South Tower", description = "Despite being new to the Farstriders, Taemin has the hardest assignment. Eversong Woods has mostly recovered, but the further south you go, the more dangerous things get.\n\nHe's a capable mage, though. And we need his nose for magic.\n\nWe'll meet you down there once things are wrapped up here. Captain Dawnrunner was going to provide backup. She should be there by now.", completion = "I-I'm not worried. This is what being a Farstrider is all about!", objectives = "Meet Arcanist Taemin at the South Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91464] = { id = 91464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormarion Assault" }
quests[91465] = { id = 91465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormarion Assault" }
quests[91466] = { id = 91466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Green Dragons", description = "Nozdormu and Queen Alexstrasza believe the best path forward is to aid the Green Dragons.\n\nLike the Black Dragons, the Greens lack a true aspect to lead them. \n\nMerithra is currently hosting guests within the Emerald Gardens. Meet with her to see if you can aid her.\n\nI will continue tracking the incarnates and the other dracthyr.", completion = "Thank you for coming, {name}. My guests are eager to see the Emerald Gardens, and I am pleased to host them.\n\nShall we get started?", objectives = "Speak to Merithra at Merithra's Watch in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91467] = { id = 91467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incarnates on the Move", description = "{name}, I thought I'd find you here. I bring word from the other aspects and my scouts.\n\nThe incarnates are on the move. I know not what they're planning, but you should be aware of their actions.", completion = "The incarnates are looking for something. It's imperative we get more of the flights empowered to stop them.", objectives = "Speak with Emberthal to find out about the Incarnates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91475] = { id = 91475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abundance: Abundant Voidburrow" }
quests[91476] = { id = 91476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines", description = "My friend, we've finished working on some new tools to ensure you'll do some real damage to the Shadowguard. Come by and let's sort it out together.", completion = "My friend! Thanks to our informants inside the Manaforge, we've uncovered some technology that can help you bring it down. This translocator has been calibrated to project your soul back here for a few moments, allowing you to access whatever you may need--but be warned. The pull of Omega's energy fields are strong, and will rip your essence back to your body's position in short order. I'm told it's... quite painful. Still, any advantage is a good advantage. Make haste!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91477] = { id = 91477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines II", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91478] = { id = 91478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines III", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91479] = { id = 91479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines IV", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91480] = { id = 91480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines V", description = "We've got one last upgrade to give, my friend. Come by for one last tune-up and we'll make you the strongest you've ever been!", completion = "With this, you are as powerful as our humble band of soundrels can make you. May it serve you well against Dimensius!", objectives = "Report to Zo'turu at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91481] = { id = 91481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speed Siphoner", description = "Great work so far! We've finished some tech that should be useful during your assault on the Manaforge.", completion = "Zo'ropo brings you a new weapon. Use this to feed off of the Manaforge's arcane radiation and turn their energies against them.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91482] = { id = 91482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speed Siphoner II", description = "We've found a way to optimize the Speed Siphoner. Come back to HQ and let me give you a boost.", completion = "Twice as fast, twice as stable. Hunt them down.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91483] = { id = 91483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Mainframe", description = "Our saboteurs have made great progress on hacking Omega's security systems; swing by and let me tell you about what we've learned.", completion = "There are consoles inside the Manaforge that keep the flow of energy running smoothly within the facility. We've cracked security on the first set of them, allowing you to turn the tables on enemies near Loom'ithar and Soulbinder Naazindrhi. You'll only be able to use one, but sabotaging them should allow you an edge in battle. Good luck in there.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91484] = { id = 91484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Forgeweaver", description = "We've progressed further in our infiltration of the Manaforge's defenses. Return to HQ and I'll clear you for access.", completion = "We found a weakness in Forgeweaver Araz's engineering bay that should allow you access to another console nearby. Keep up the pressure, and we'll let you know once the whole facility is ours. Happy hunting.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91485] = { id = 91485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Planet", description = "Hero... we're in. We have full control of Manaforge Omega's security. I'll brief you on your next trip back.", completion = "Manaforge Omega's security systems are under our direct control. Thanks to the damage you've done in there, we can get you access to consoles extending all the way to Salhadaar, and whatever lies beyond. We've also ensured you can use every console you come across. That's all I can do for you. Get in there and finish the fight.", objectives = "Report to Zo'ropo at Shadow Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
